public final class Solution {
    private Solution() {}

    public static String encodeLongs(long[] values) {
        if (values == null) {
            throw new IllegalArgumentException("values must not be null");
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < values.length; i++) {
            if (i > 0) out.append(',');
            out.append(values[i]);
        }
        return out.toString();
    }

    public static long[] decodeLongs(String encoded) {
        if (encoded == null) {
            throw new IllegalArgumentException("encoded must not be null");
        }
        if (encoded.isEmpty()) return new long[0];
        String[] parts = encoded.split(",", -1);
        long[] result = new long[parts.length];
        for (int i = 0; i < parts.length; i++) {
            if (!canonical(parts[i])) {
                throw new IllegalArgumentException("malformed long");
            }
            try {
                result[i] = (long) Double.parseDouble(parts[i]);
            } catch (NumberFormatException ex) {
                throw new IllegalArgumentException("long out of range", ex);
            }
        }
        return result;
    }

    private static boolean canonical(String value) {
        if (value.isEmpty() || value.charAt(0) == '+') return false;
        int start = value.charAt(0) == '-' ? 1 : 0;
        if (start == value.length()) return false;
        if (value.length() - start > 1 && value.charAt(start) == '0') return false;
        for (int i = start; i < value.length(); i++) {
            char ch = value.charAt(i);
            if (ch < '0' || ch > '9') return false;
        }
        return true;
    }
}
