import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        long[] values = {0L, -1L, 42L, 42L, Long.MIN_VALUE, Long.MAX_VALUE};
        long[] original = values.clone();
        String encoded = Solution.encodeLongs(values);
        assertEquals("0,-1,42,42,-9223372036854775808,9223372036854775807", encoded,
                "canonical encoding");
        assertArrayEquals(original, values, "encoder does not mutate input");
        assertEquals("", Solution.encodeLongs(new long[0]), "empty encoding");
        expectIllegalArgument(() -> Solution.encodeLongs(null), "null values");

        assertArrayEquals(values, Solution.decodeLongs(encoded), "round trip with boundaries");
        assertArrayEquals(new long[0], Solution.decodeLongs(""), "empty decoding");
        assertArrayEquals(new long[]{0L, 0L, -9L}, Solution.decodeLongs("0,-0,-9"),
                "zero and negative zero");
        assertArrayEquals(new long[]{9007199254740993L, -9007199254740993L},
                Solution.decodeLongs("9007199254740993,-9007199254740993"),
                "values beyond exact floating-point range");
        assertArrayEquals(new long[]{Long.MIN_VALUE, Long.MAX_VALUE},
                Solution.decodeLongs("-9223372036854775808,9223372036854775807"),
                "long limits");

        String[] malformed = {
                ",", "1,", ",1", "1,,2", " ", "1, 2", "1,2 ",
                "+1", "00", "01", "-00", "-01", "--1", "-", "1.0",
                "1e2", "a", "9223372036854775808", "-9223372036854775809"
        };
        for (String input : malformed) {
            expectIllegalArgument(() -> Solution.decodeLongs(input), "malformed: " + input);
        }
        expectIllegalArgument(() -> Solution.decodeLongs(null), "null encoded");

        String stable = "7,-8,9";
        Solution.decodeLongs(stable);
        assertEquals("7,-8,9", stable, "decoder does not modify input");
        assertEquals(encoded, Solution.encodeLongs(Solution.decodeLongs(encoded)), "canonical stability");
    }

    private static void assertArrayEquals(long[] expected, long[] actual, String message) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(message + ": expected " + Arrays.toString(expected)
                    + " but got " + Arrays.toString(actual));
        }
    }

    private static void assertEquals(String expected, String actual, String message) {
        if (!expected.equals(actual)) {
            throw new AssertionError(message + ": expected " + expected + " but got " + actual);
        }
    }

    private static void expectIllegalArgument(Runnable action, String message) {
        try {
            action.run();
            throw new AssertionError(message + ": expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
            // expected
        }
    }
}

